package com.regionobjectmarkers;

enum Filter
{
	ALL,
	REGION,
	VISIBLE,
	INVISIBLE;

	private static final Filter[] FILTERS = values();

	public Filter next()
	{
		return FILTERS[(this.ordinal() + 1) % FILTERS.length];
	}
}

package com.regionobjectmarkers;

public enum MarkerStyle
{
	HULL,
	CLICKBOX,
	TILE,
	OUTLINE
}

package com.regionobjectmarkers;

import java.awt.Color;
import lombok.Data;

@Data
class ObjectMarker
{
	private String name = "Object name";
	private boolean visible = true;
	private MarkerStyle style = MarkerStyle.HULL;
	private Color fillColor = new Color(0, 255, 0, 50);
	private Color outlineColor = Color.GREEN;
	private int outlineWidth = 2;
	private boolean interactableOnly;
}

package com.regionobjectmarkers;

import java.util.ArrayList;
import java.util.List;
import lombok.Data;

@Data
class RegionMarkerSection
{
	private String name;
	/** Legacy single-value field retained only so existing saved sections migrate cleanly. */
	private Integer regionId;
	private List<Integer> regionIds = new ArrayList<>();
	private boolean allRegions;
	private boolean visible = true;
	private boolean collapsed;
	private List<ObjectMarker> objects = new ArrayList<>();

	RegionMarkerSection(String name)
	{
		this.name = name;
	}

	void normalizeRegionIds()
	{
		if (regionIds == null)
		{
			regionIds = new ArrayList<>();
		}
		if (regionIds.isEmpty() && regionId != null)
		{
			regionIds.add(regionId);
		}
		regionId = null;
	}
}

package com.regionobjectmarkers;

import java.awt.*;
import java.awt.image.BufferedImage;
import javax.swing.*;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.components.FlatTextField;
import net.runelite.client.ui.components.colorpicker.RuneliteColorPicker;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.SwingUtil;

final class RegionObjectMarkerSectionPanel extends JPanel
{
	private static final ImageIcon PENCIL_ICON;
	private static final ImageIcon RIGHT_ICON;
	private static final ImageIcon DOWN_ICON;
	private static final ImageIcon PAINT_ICON;
	private static final ImageIcon VISIBLE_ICON;
	private static final ImageIcon INVISIBLE_ICON;
	static
	{
		BufferedImage pencil = ImageUtil.loadImageResource(RegionObjectMarkersPlugin.class, "settings_icon.png");
		PENCIL_ICON = new ImageIcon(pencil); PAINT_ICON = new ImageIcon(pencil);
		BufferedImage arrow = ImageUtil.loadImageResource(RegionObjectMarkersPlugin.class, "arrow_right.png");
		RIGHT_ICON = new ImageIcon(arrow); DOWN_ICON = new ImageIcon(ImageUtil.rotateImage(arrow, Math.PI / 2));
		VISIBLE_ICON = new ImageIcon(ImageUtil.loadImageResource(RegionObjectMarkersPlugin.class, "visible_icon.png"));
		INVISIBLE_ICON = new ImageIcon(ImageUtil.loadImageResource(RegionObjectMarkersPlugin.class, "invisible_icon.png"));
	}
	private final RegionObjectMarkersPlugin plugin;
	private final RegionMarkerSection section;
	private final JPanel content = new JPanel();
	private final JPanel objectRows = new JPanel();
	private final JButton expand = new JButton();
	private final FlatTextField sectionName = new FlatTextField();

	RegionObjectMarkerSectionPanel(RegionObjectMarkersPlugin plugin, RegionMarkerSection section, Filter filter)
	{
		this.plugin = plugin; this.section = section;
		setLayout(new BorderLayout()); setBackground(ColorScheme.DARKER_GRAY_COLOR);
		add(header(), BorderLayout.NORTH);
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS)); content.setBackground(ColorScheme.DARKER_GRAY_COLOR); content.setBorder(BorderFactory.createEmptyBorder(6, 7, 7, 7));
		content.add(groupLabel("REGION SELECTION")); content.add(Box.createRigidArea(new Dimension(0, 4))); content.add(regionRow());
		content.add(Box.createRigidArea(new Dimension(0, 2))); JSeparator divider = new JSeparator(); divider.setForeground(ColorScheme.DARK_GRAY_COLOR); divider.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1)); content.add(divider); content.add(Box.createRigidArea(new Dimension(0, 4))); content.add(groupLabel("OBJECT MARKERS"));
		objectRows.setLayout(new BoxLayout(objectRows, BoxLayout.Y_AXIS)); objectRows.setBackground(ColorScheme.DARKER_GRAY_COLOR); objectRows.setAlignmentX(LEFT_ALIGNMENT);
		for (ObjectMarker object : section.getObjects()) if (filter == Filter.ALL || filter == Filter.REGION || (filter == Filter.VISIBLE && object.isVisible()) || (filter == Filter.INVISIBLE && !object.isVisible())) { objectRows.add(Box.createRigidArea(new Dimension(0, 5))); objectRows.add(new ObjectRow(object)); }
		content.add(objectRows); content.add(Box.createRigidArea(new Dimension(0, 5))); JButton add = new JButton("+ Add object"); add.setToolTipText("Add an object-name highlight to this section"); add.addActionListener(e -> { section.getObjects().add(plugin.newObjectMarker()); plugin.saveSections(); plugin.rebuild(); }); content.add(add); add(content, BorderLayout.CENTER);
		setExpanded(!section.isCollapsed(), false);
	}
	private JPanel header()
	{
		JPanel header = new JPanel(new BorderLayout()); header.setBackground(ColorScheme.DARKER_GRAY_COLOR); header.setBorder(BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR));
		expand.setPreferredSize(new Dimension(22, 24)); SwingUtil.removeButtonDecorations(expand); expand.addActionListener(e -> setExpanded(!content.isVisible(), true)); header.add(expand, BorderLayout.WEST);
		sectionName.setText(section.getName()); sectionName.setToolTipText("Object marker section name"); sectionName.setEditable(false); sectionName.setBackground(ColorScheme.DARKER_GRAY_COLOR); sectionName.getTextField().setForeground(Color.WHITE); sectionName.getTextField().setFont(FontManager.getRunescapeSmallFont()); header.add(sectionName, BorderLayout.CENTER);
		JPanel actions = new JPanel(new FlowLayout(FlowLayout.RIGHT, 8, 0)); actions.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		JLabel rename = new JLabel(PENCIL_ICON); rename.setToolTipText("Edit section name"); JLabel save = saveIcon("Save section name"); save.setVisible(false);
		rename.addMouseListener(new java.awt.event.MouseAdapter() { @Override public void mousePressed(java.awt.event.MouseEvent e) { sectionName.setEditable(true); sectionName.getTextField().requestFocusInWindow(); sectionName.getTextField().selectAll(); rename.setVisible(false); save.setVisible(true); actions.revalidate(); } });
		save.addMouseListener(new java.awt.event.MouseAdapter() { @Override public void mousePressed(java.awt.event.MouseEvent e) { String value = sectionName.getText().trim(); if (!value.isEmpty()) { section.setName(value); plugin.saveSections(); } sectionName.setEditable(false); save.setVisible(false); rename.setVisible(true); actions.revalidate(); } }); actions.add(rename); actions.add(save);
		actions.add(visibility(section::isVisible, section::setVisible, "region section"));
		JButton delete = new JButton("×"); delete.setForeground(Color.WHITE); delete.setToolTipText("Delete region section"); SwingUtil.removeButtonDecorations(delete); delete.addActionListener(e -> { if (confirmDelete("section '" + section.getName() + "'")) plugin.removeSection(section); }); actions.add(delete); header.add(actions, BorderLayout.EAST); return header;
	}
	private JPanel regionRow()
	{
		JPanel rows = new JPanel(); rows.setLayout(new BoxLayout(rows, BoxLayout.Y_AXIS)); rows.setBackground(ColorScheme.DARKER_GRAY_COLOR); rows.setAlignmentX(LEFT_ALIGNMENT);
		JPanel modeRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 0)); modeRow.setBackground(ColorScheme.DARKER_GRAY_COLOR); modeRow.setAlignmentX(LEFT_ALIGNMENT);
		modeRow.add(label("Scope"));
		JCheckBox allRegions = new JCheckBox("All regions", section.isAllRegions()); allRegions.setToolTipText("Match this section in every region; saved Region IDs are retained"); allRegions.setForeground(ColorScheme.LIGHT_GRAY_COLOR); allRegions.setBackground(ColorScheme.DARKER_GRAY_COLOR); allRegions.setFont(FontManager.getRunescapeSmallFont()); allRegions.setBorder(BorderFactory.createEmptyBorder()); allRegions.setFocusPainted(false);
		modeRow.add(allRegions); modeRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, modeRow.getPreferredSize().height)); rows.add(modeRow);
		JPanel row = new JPanel(new BorderLayout(6, 0)); row.setBackground(ColorScheme.DARKER_GRAY_COLOR); row.setAlignmentX(LEFT_ALIGNMENT); JLabel label = label("Region IDs"); row.add(label, BorderLayout.WEST);
		FlatTextField regions = new FlatTextField(); regions.setText(section.isAllRegions() ? "" : formatRegionIds()); regions.setBackground(ColorScheme.DARK_GRAY_COLOR); regions.setToolTipText("Comma-separated region IDs, for example: 9265, 9266"); regions.setEditable(false); regions.setEnabled(!section.isAllRegions());
		JPanel regionActions = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0)); regionActions.setBackground(ColorScheme.DARKER_GRAY_COLOR); JLabel edit = new JLabel(PENCIL_ICON); edit.setToolTipText("Edit region IDs"); JLabel save = saveIcon("Save region IDs"); save.setVisible(false); regionActions.add(edit); regionActions.add(save);
		edit.addMouseListener(new java.awt.event.MouseAdapter() { @Override public void mousePressed(java.awt.event.MouseEvent e) { if (!section.isAllRegions()) { regions.setEditable(true); regions.getTextField().requestFocusInWindow(); edit.setVisible(false); save.setVisible(true); regionActions.revalidate(); } } });
		save.addMouseListener(new java.awt.event.MouseAdapter() { @Override public void mousePressed(java.awt.event.MouseEvent e) { if (saveRegionIds(regions)) { regions.setEditable(false); save.setVisible(false); edit.setVisible(true); regionActions.revalidate(); } } });
		allRegions.addActionListener(e -> { section.setAllRegions(allRegions.isSelected()); regions.setEnabled(!section.isAllRegions()); regions.setEditable(false); regions.setText(section.isAllRegions() ? "" : formatRegionIds()); save.setVisible(false); edit.setVisible(!section.isAllRegions()); plugin.saveSections(); });
		row.add(regions, BorderLayout.CENTER); row.add(regionActions, BorderLayout.EAST); row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height)); rows.add(row); rows.setMaximumSize(new Dimension(Integer.MAX_VALUE, rows.getPreferredSize().height)); return rows;
	}
	private String formatRegionIds()
	{
		StringBuilder result = new StringBuilder();
		for (Integer regionId : section.getRegionIds()) { if (result.length() > 0) result.append(", "); result.append(regionId); }
		return result.toString();
	}
	private boolean saveRegionIds(FlatTextField field)
	{
		if (section.isAllRegions()) return false;
		java.util.List<Integer> parsed = new java.util.ArrayList<>(); String value = field.getText().trim();
		try
		{
			if (!value.isEmpty()) for (String part : value.split(",")) { int id = Integer.parseInt(part.trim()); if (id < 0) throw new NumberFormatException(); if (!parsed.contains(id)) parsed.add(id); }
		}
		catch (NumberFormatException ex)
		{
			field.getTextField().setForeground(Color.RED); field.setToolTipText("Use comma-separated non-negative region IDs, for example: 9265, 9266"); return false;
		}
		field.getTextField().setForeground(Color.WHITE); section.setRegionIds(parsed); plugin.saveSections(); return true;
	}
	private void setExpanded(boolean expanded, boolean persist) { content.setVisible(expanded); expand.setIcon(expanded ? DOWN_ICON : RIGHT_ICON); expand.setToolTipText(expanded ? "Collapse section" : "Expand section"); if (persist) { section.setCollapsed(!expanded); plugin.saveSections(false); } revalidate(); }
	private JLabel visibility(java.util.function.BooleanSupplier get, java.util.function.Consumer<Boolean> set, String subject)
	{
		JLabel icon = new JLabel(get.getAsBoolean() ? VISIBLE_ICON : INVISIBLE_ICON); icon.setToolTipText(get.getAsBoolean() ? "Hide " + subject : "Show " + subject);
		icon.addMouseListener(new java.awt.event.MouseAdapter() { @Override public void mousePressed(java.awt.event.MouseEvent e) { set.accept(!get.getAsBoolean()); plugin.saveSections(); plugin.rebuild(); } }); return icon;
	}
	private JLabel label(String text) { JLabel label = new JLabel(text); label.setForeground(ColorScheme.LIGHT_GRAY_COLOR.darker()); label.setFont(FontManager.getRunescapeSmallFont()); return label; }
	private JLabel groupLabel(String text) { JLabel label = label(text); label.setForeground(ColorScheme.LIGHT_GRAY_COLOR); label.setAlignmentX(LEFT_ALIGNMENT); return label; }
	private JLabel saveIcon(String tooltip) { JLabel icon = new JLabel("✓"); icon.setForeground(Color.GREEN); icon.setFont(FontManager.getRunescapeSmallFont()); icon.setToolTipText(tooltip); return icon; }
	private boolean confirmDelete(String subject)
	{
		return JOptionPane.showConfirmDialog(this, "Delete " + subject + "?", "Confirm deletion", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE) == JOptionPane.YES_OPTION;
	}

	private final class ObjectRow extends JPanel
	{
		private final ObjectMarker marker;
		ObjectRow(ObjectMarker marker)
		{
			this.marker = marker; setLayout(new BorderLayout(0, 4)); setBackground(ColorScheme.DARKER_GRAY_COLOR); setBorder(BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(1, 0, 0, 0, ColorScheme.DARK_GRAY_COLOR), BorderFactory.createEmptyBorder(5, 0, 5, 0)));
			FlatTextField name = new FlatTextField(); name.setText(marker.getName()); name.setToolTipText("Object name; * matches any characters"); name.setBackground(ColorScheme.DARK_GRAY_COLOR); name.getTextField().setForeground(Color.WHITE); name.setEditable(false);
			JPanel nameRow = new JPanel(new BorderLayout(6, 0)); nameRow.setBackground(ColorScheme.DARKER_GRAY_COLOR); nameRow.add(name, BorderLayout.CENTER); JPanel actions = new JPanel(new FlowLayout(FlowLayout.RIGHT, 5, 0)); actions.setBackground(ColorScheme.DARKER_GRAY_COLOR); JLabel edit = new JLabel(PENCIL_ICON); edit.setToolTipText("Edit object name"); JLabel save = saveIcon("Save object name"); save.setVisible(false); edit.addMouseListener(new java.awt.event.MouseAdapter() { @Override public void mousePressed(java.awt.event.MouseEvent e) { name.setEditable(true); name.getTextField().requestFocusInWindow(); name.getTextField().selectAll(); edit.setVisible(false); save.setVisible(true); actions.revalidate(); } }); save.addMouseListener(new java.awt.event.MouseAdapter() { @Override public void mousePressed(java.awt.event.MouseEvent e) { marker.setName(name.getText().trim()); plugin.saveSections(); name.setEditable(false); save.setVisible(false); edit.setVisible(true); actions.revalidate(); } }); actions.add(edit); actions.add(save); actions.add(visibility(marker::isVisible, marker::setVisible, "object marker")); JButton delete = new JButton("×"); delete.setForeground(Color.WHITE); delete.setToolTipText("Delete this object marker"); SwingUtil.removeButtonDecorations(delete); delete.addActionListener(e -> { if (confirmDelete("object marker '" + marker.getName() + "'")) { section.getObjects().remove(marker); plugin.saveSections(); plugin.rebuild(); } }); actions.add(delete); nameRow.add(actions, BorderLayout.EAST); add(nameRow, BorderLayout.NORTH);
			JPanel controls = new JPanel(); controls.setLayout(new BoxLayout(controls, BoxLayout.Y_AXIS)); controls.setBackground(ColorScheme.DARKER_GRAY_COLOR); JPanel styleRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0)); styleRow.setBackground(ColorScheme.DARKER_GRAY_COLOR); styleRow.add(label("Style")); JComboBox<MarkerStyle> style = new JComboBox<>(MarkerStyle.values()); style.setToolTipText("Choose Hull, Clickbox, Tile, or Outline rendering"); style.setSelectedItem(marker.getStyle()); style.setPreferredSize(new Dimension(85, 22)); style.addActionListener(e -> { marker.setStyle((MarkerStyle) style.getSelectedItem()); plugin.saveSections(); }); styleRow.add(style); JCheckBox interactableOnly = new JCheckBox("Interactable"); interactableOnly.setSelected(marker.isInteractableOnly()); interactableOnly.setBackground(ColorScheme.DARKER_GRAY_COLOR); interactableOnly.setForeground(ColorScheme.LIGHT_GRAY_COLOR); interactableOnly.setFont(FontManager.getRunescapeSmallFont()); interactableOnly.setToolTipText("Only highlight objects that have at least one in-game object action"); interactableOnly.addActionListener(e -> { marker.setInteractableOnly(interactableOnly.isSelected()); plugin.saveSections(); }); JPanel optionRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0)); optionRow.setBackground(ColorScheme.DARKER_GRAY_COLOR); optionRow.add(interactableOnly); JPanel colorRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 8, 2)); colorRow.setBackground(ColorScheme.DARKER_GRAY_COLOR); colorRow.add(label("Fill")); colorRow.add(color(true)); colorRow.add(label("Outline")); colorRow.add(color(false)); JSpinner outlineWidth = new JSpinner(new SpinnerNumberModel(Math.max(0, Math.min(10, marker.getOutlineWidth())), 0, 10, 1)); outlineWidth.setPreferredSize(new Dimension(52, 22)); outlineWidth.setMinimumSize(new Dimension(52, 22)); ((JSpinner.DefaultEditor) outlineWidth.getEditor()).getTextField().setColumns(2); outlineWidth.setToolTipText("Outline thickness in pixels; 0 disables the outline"); outlineWidth.addChangeListener(e -> { marker.setOutlineWidth((Integer) outlineWidth.getValue()); plugin.saveSections(); }); colorRow.add(outlineWidth); controls.add(styleRow); controls.add(optionRow); controls.add(colorRow); add(controls, BorderLayout.CENTER);
		}
		private JLabel color(boolean fill)
		{
			JLabel button = new JLabel(PAINT_ICON); Color initial = fill ? marker.getFillColor() : marker.getOutlineColor(); button.setBorder(BorderFactory.createMatteBorder(0, 0, 3, 0, previewColor(initial))); button.setToolTipText(fill ? "Edit fill color" : "Edit outline color"); button.addMouseListener(new java.awt.event.MouseAdapter() { @Override public void mousePressed(java.awt.event.MouseEvent e) { pick(fill, button); } }); return button;
		}
		private void pick(boolean fill, JLabel button)
		{
			Color current = fill ? marker.getFillColor() : marker.getOutlineColor(); RuneliteColorPicker picker = plugin.getColourPickerManager().create(SwingUtilities.windowForComponent(this), current, fill ? "Object fill color" : "Object outline color", false); picker.setOnColorChange(color -> { if (fill) marker.setFillColor(color); else marker.setOutlineColor(color); button.setBorder(BorderFactory.createMatteBorder(0, 0, 3, 0, previewColor(color))); button.repaint(); plugin.saveSections(); }); picker.setVisible(true);
		}
		private Color previewColor(Color color) { return new Color(color.getRed(), color.getGreen(), color.getBlue()); }
	}
}

package com.regionobjectmarkers;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(RegionObjectMarkersPlugin.CONFIG_GROUP)
public interface RegionObjectMarkersConfig extends Config
{
	@ConfigItem(keyName = "defaultStyle", name = "Default highlight style", description = "Highlight style used by newly added object markers")
	default MarkerStyle defaultStyle()
	{
		return MarkerStyle.HULL;
	}

	@Alpha
	@ConfigItem(keyName = "defaultFillColor", name = "Default fill color", description = "Fill color used by newly added object markers")
	default Color defaultFillColor()
	{
		return new Color(0, 255, 0, 50);
	}

	@ConfigItem(keyName = "defaultOutlineColor", name = "Default outline color", description = "Outline color used by newly added object markers")
	default Color defaultOutlineColor()
	{
		return Color.GREEN;
	}

	@Range(min = 0, max = 10)
	@ConfigItem(keyName = "defaultOutlineWidth", name = "Default outline width", description = "Outline width used by newly added object markers; 0 disables the outline")
	default int defaultOutlineWidth()
	{
		return 2;
	}

	@ConfigItem(keyName = "defaultInteractableOnly", name = "Default interactable-only", description = "Only match objects with an available object action when creating new markers")
	default boolean defaultInteractableOnly()
	{
		return false;
	}

	@ConfigItem(keyName = "debugTextColor", name = "Debug text color", description = "Text color used by hover information and scene object labels")
	default Color debugTextColor()
	{
		return Color.GREEN;
	}
}

package com.regionobjectmarkers;

import com.google.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

class RegionObjectMarkersDebugOverlay extends Overlay
{
	private static final int REGION_SIZE = 64;
	private static final int CHUNK_SIZE = 8;
	private static final int REGION_HEIGHT_OFFSET = 32;
	private static final BasicStroke HOVER_STROKE = new BasicStroke(2);
	private static final BasicStroke REGION_STROKE = new BasicStroke(1);
	private final Client client;
	private final RegionObjectMarkersPlugin plugin;
	private final List<RegionGeometry> cachedRegionGeometry = new ArrayList<>();
	private Scene cachedRegionScene;
	private int cachedRegionPlane = -1;
	private int cachedRegionBaseX;
	private int cachedRegionBaseY;
	private int cachedRegionWidth;
	private int cachedRegionHeight;
	private boolean cachedRegionInstance;
	private int cachedInstanceTemplateFingerprint;

	@Inject
	RegionObjectMarkersDebugOverlay(Client client, RegionObjectMarkersPlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		boolean hoverInfo = plugin.isDebugHoverInfo();
		boolean objectLabels = plugin.isDebugObjectLabels();
		boolean regions = plugin.isDebugRegions();
		if (!hoverInfo && !objectLabels && !regions)
		{
			return null;
		}

		if (regions)
		{
			renderRegions(graphics);
		}
		if (objectLabels)
		{
			renderObjectLabels(graphics);
		}
		if (hoverInfo)
		{
			renderHoverInfo(graphics);
		}
		return null;
	}

	private void renderHoverInfo(Graphics2D graphics)
	{
		Tile tile = client.getSelectedSceneTile();
		if (tile == null || tile.getWorldLocation() == null)
		{
			return;
		}

		WorldPoint point = WorldPoint.fromLocalInstance(client, tile.getLocalLocation(), tile.getPlane());
		List<String> lines = new ArrayList<>();
		lines.add("World location: " + point.getX() + ", " + point.getY() + ", " + point.getPlane());
		lines.add("Hovered region: " + point.getRegionID() + " location: " + (point.getX() & 63) + ", " + (point.getY() & 63));
		if (client.getLocalPlayer() != null)
		{
			WorldPoint playerPoint = WorldPoint.fromLocalInstance(client, client.getLocalPlayer().getLocalLocation());
			lines.add("Player region: " + playerPoint.getRegionID());
		}

		Shape tilePolygon = Perspective.getCanvasTilePoly(client, tile.getLocalLocation(), point.getPlane());
		net.runelite.api.Point mouse = client.getMouseCanvasPosition();
		int x = mouse.getX() + 12;
		int y = mouse.getY() + 14;
		if (tilePolygon != null)
		{
			graphics.setColor(plugin.getDebugTextColor());
			graphics.setStroke(HOVER_STROKE);
			graphics.draw(tilePolygon);
			java.awt.Rectangle bounds = tilePolygon.getBounds();
			x = bounds.x + 4;
			y = bounds.y + bounds.height + 14;
		}

		FontMetrics metrics = graphics.getFontMetrics();
		for (String line : lines)
		{
			graphics.setColor(Color.BLACK);
			graphics.drawString(line, x + 1, y + 1);
			graphics.setColor(plugin.getDebugTextColor());
			graphics.drawString(line, x, y);
			y += metrics.getHeight();
		}
	}

	private void renderObjectLabels(Graphics2D graphics)
	{
		for (Map.Entry<TileObject, String> entry : plugin.getDebugObjects().entrySet())
		{
			net.runelite.api.Point location = entry.getKey().getCanvasTextLocation(graphics, entry.getValue(), 0);
			if (location != null)
			{
				OverlayUtil.renderTextLocation(graphics, location, entry.getValue(), plugin.getDebugTextColor());
			}
		}
	}

	private void renderRegions(Graphics2D graphics)
	{
		Scene scene = client.getScene();
		Tile[][][] tiles = scene == null ? null : scene.getTiles();
		int plane = client.getPlane();
		if (tiles == null || plane < 0 || plane >= tiles.length || tiles[plane].length == 0)
		{
			return;
		}
		int elevation = regionElevation(tiles[plane], plane);

		List<RegionGeometry> regions = regionGeometry(scene, tiles[plane], plane);
		graphics.setColor(plugin.getDebugTextColor());
		graphics.setStroke(REGION_STROKE);
		for (RegionGeometry region : regions)
		{
			for (RegionEdge edge : region.edges)
			{
				renderRegionEdge(graphics, scene, edge.startX, edge.startY, edge.endX, edge.endY, elevation);
			}
			renderRegionLabel(graphics, scene, region.labelX, region.labelY, elevation, region.label);
		}
	}

	private List<RegionGeometry> regionGeometry(Scene scene, Tile[][] tiles, int plane)
	{
		int templateFingerprint = scene.isInstance() ? instanceTemplateFingerprint(scene.getInstanceTemplateChunks(), plane) : 0;
		if (scene == cachedRegionScene && scene.isInstance() == cachedRegionInstance && plane == cachedRegionPlane && scene.getBaseX() == cachedRegionBaseX
			&& scene.getBaseY() == cachedRegionBaseY && tiles.length == cachedRegionWidth
			&& tiles[0].length == cachedRegionHeight && templateFingerprint == cachedInstanceTemplateFingerprint)
		{
			return cachedRegionGeometry;
		}

		cachedRegionGeometry.clear();
		if (scene.isInstance())
		{
			buildInstanceRegionGeometry(scene, tiles, plane, cachedRegionGeometry);
		}
		else
		{
			buildWorldRegionGeometry(scene, tiles, plane, cachedRegionGeometry);
		}
		cachedRegionScene = scene;
		cachedRegionPlane = plane;
		cachedRegionBaseX = scene.getBaseX();
		cachedRegionBaseY = scene.getBaseY();
		cachedRegionWidth = tiles.length;
		cachedRegionHeight = tiles[0].length;
		cachedRegionInstance = scene.isInstance();
		cachedInstanceTemplateFingerprint = templateFingerprint;
		return cachedRegionGeometry;
	}

	private int instanceTemplateFingerprint(int[][][] templateChunks, int plane)
	{
		if (templateChunks == null || plane < 0 || plane >= templateChunks.length || templateChunks[plane] == null)
		{
			return 0;
		}
		int fingerprint = 1;
		for (int[] column : templateChunks[plane])
		{
			fingerprint = 31 * fingerprint + (column == null ? 0 : column.length);
			if (column != null)
			{
				for (int chunk : column) fingerprint = 31 * fingerprint + chunk;
			}
		}
		return fingerprint;
	}

	private int regionElevation(Tile[][] tiles, int plane)
	{
		if (client.getLocalPlayer() != null)
		{
			return Perspective.getTileHeight(client, client.getLocalPlayer().getLocalLocation(), plane) - REGION_HEIGHT_OFFSET;
		}
		for (Tile[] column : tiles)
		{
			for (Tile tile : column)
			{
				if (tile != null)
				{
					return Perspective.getTileHeight(client, tile.getLocalLocation(), plane) - REGION_HEIGHT_OFFSET;
				}
			}
		}
		return -REGION_HEIGHT_OFFSET;
	}

	private void buildWorldRegionGeometry(Scene scene, Tile[][] tiles, int plane, List<RegionGeometry> regions)
	{
		int firstX = -(scene.getBaseX() & (REGION_SIZE - 1));
		int firstY = -(scene.getBaseY() & (REGION_SIZE - 1));
		for (int x = firstX; x < tiles.length; x += REGION_SIZE)
		{
			int startX = Math.max(0, x);
			int width = Math.min(tiles.length, x + REGION_SIZE) - startX;
			for (int y = firstY; y < tiles[startX].length; y += REGION_SIZE)
			{
				int startY = Math.max(0, y);
				int height = Math.min(tiles[startX].length, y + REGION_SIZE) - startY;
				if (width <= 0 || height <= 0)
				{
					continue;
				}
				WorldPoint point = WorldPoint.fromLocalInstance(client, LocalPoint.fromScene(startX, startY, scene), plane);
				regions.add(RegionGeometry.rectangle(startX, startY, width, height, "Region " + point.getRegionID()));
			}
		}
	}

	private void buildInstanceRegionGeometry(Scene scene, Tile[][] tiles, int plane, List<RegionGeometry> regions)
	{
		int chunksX = tiles.length / CHUNK_SIZE;
		int chunksY = tiles[0].length / CHUNK_SIZE;
		int[][][] templateChunks = scene.getInstanceTemplateChunks();
		int[][] regionIds = new int[chunksX][chunksY];
		for (int[] column : regionIds)
		{
			Arrays.fill(column, -1);
		}

		for (int x = 0; x < chunksX; x++)
		{
			for (int y = 0; y < chunksY; y++)
			{
				if (!isMappedInstanceChunk(templateChunks, plane, x, y))
				{
					continue;
				}
				regionIds[x][y] = WorldPoint.fromLocalInstance(client, LocalPoint.fromScene(x * CHUNK_SIZE, y * CHUNK_SIZE, scene), plane).getRegionID();
			}
		}

		boolean[][] visited = new boolean[chunksX][chunksY];
		for (int x = 0; x < chunksX; x++)
		{
			for (int y = 0; y < chunksY; y++)
			{
				if (visited[x][y] || regionIds[x][y] == -1)
				{
					continue;
				}
				int regionId = regionIds[x][y];
				ArrayDeque<int[]> pending = new ArrayDeque<>();
				pending.add(new int[] {x, y});
				visited[x][y] = true;
				int centerX = 0;
				int centerY = 0;
				int count = 0;
				List<int[]> component = new ArrayList<>();
				while (!pending.isEmpty())
				{
					int[] chunk = pending.removeFirst();
					component.add(chunk);
					centerX += chunk[0] * CHUNK_SIZE + CHUNK_SIZE / 2;
					centerY += chunk[1] * CHUNK_SIZE + CHUNK_SIZE / 2;
					count++;
					addMatchingChunk(pending, visited, regionIds, chunk[0] - 1, chunk[1], regionId);
					addMatchingChunk(pending, visited, regionIds, chunk[0] + 1, chunk[1], regionId);
					addMatchingChunk(pending, visited, regionIds, chunk[0], chunk[1] - 1, regionId);
					addMatchingChunk(pending, visited, regionIds, chunk[0], chunk[1] + 1, regionId);
				}
				regions.add(instanceRegionGeometry(regionIds, component, centerX / count, centerY / count, "Region " + regionId));
			}
		}
	}

	private boolean isMappedInstanceChunk(int[][][] templateChunks, int plane, int x, int y)
	{
		return templateChunks != null && plane >= 0 && plane < templateChunks.length
			&& templateChunks[plane] != null && x >= 0 && x < templateChunks[plane].length
			&& templateChunks[plane][x] != null && y >= 0 && y < templateChunks[plane][x].length
			&& templateChunks[plane][x][y] != -1;
	}

	private RegionGeometry instanceRegionGeometry(int[][] regionIds, List<int[]> component, int labelX, int labelY, String label)
	{
		List<RegionEdge> edges = new ArrayList<>();
		for (int[] chunk : component)
		{
			int x = chunk[0];
			int y = chunk[1];
			int startX = x * CHUNK_SIZE;
			int startY = y * CHUNK_SIZE;
			int regionId = regionIds[x][y];
			if (!hasSameRegion(regionIds, x, y - 1, regionId)) edges.add(new RegionEdge(startX, startY, startX + CHUNK_SIZE, startY));
			if (!hasSameRegion(regionIds, x + 1, y, regionId)) edges.add(new RegionEdge(startX + CHUNK_SIZE, startY, startX + CHUNK_SIZE, startY + CHUNK_SIZE));
			if (!hasSameRegion(regionIds, x, y + 1, regionId)) edges.add(new RegionEdge(startX + CHUNK_SIZE, startY + CHUNK_SIZE, startX, startY + CHUNK_SIZE));
			if (!hasSameRegion(regionIds, x - 1, y, regionId)) edges.add(new RegionEdge(startX, startY + CHUNK_SIZE, startX, startY));
		}
		return new RegionGeometry(edges, labelX, labelY, label);
	}

	private boolean hasSameRegion(int[][] regionIds, int x, int y, int regionId)
	{
		return x >= 0 && y >= 0 && x < regionIds.length && y < regionIds[0].length && regionIds[x][y] == regionId;
	}

	private void addMatchingChunk(ArrayDeque<int[]> pending, boolean[][] visited, int[][] regionIds, int x, int y, int regionId)
	{
		if (x >= 0 && y >= 0 && x < regionIds.length && y < regionIds[0].length && !visited[x][y] && regionIds[x][y] == regionId)
		{
			visited[x][y] = true;
			pending.add(new int[] {x, y});
		}
	}

	private void renderRegionEdge(Graphics2D graphics, Scene scene, int startX, int startY, int endX, int endY, int elevation)
	{
		int segments = Math.max(1, Math.max(Math.abs(endX - startX), Math.abs(endY - startY)) / CHUNK_SIZE);
		net.runelite.api.Point previous = projectRegionPoint(scene, startX, startY, elevation);
		for (int segment = 1; segment <= segments; segment++)
		{
			int x = startX + (endX - startX) * segment / segments;
			int y = startY + (endY - startY) * segment / segments;
			net.runelite.api.Point current = projectRegionPoint(scene, x, y, elevation);
			if (previous != null && current != null)
			{
				graphics.drawLine(previous.getX(), previous.getY(), current.getX(), current.getY());
			}
			previous = current;
		}
	}

	private net.runelite.api.Point projectRegionPoint(Scene scene, int x, int y, int elevation)
	{
		LocalPoint point = LocalPoint.fromScene(x, y, scene);
		return Perspective.localToCanvas(client, point.getX(), point.getY(), elevation);
	}

	private void renderRegionLabel(Graphics2D graphics, Scene scene, int x, int y, int elevation, String label)
	{
		net.runelite.api.Point location = projectRegionPoint(scene, x, y, elevation);
		if (location != null)
		{
			OverlayUtil.renderTextLocation(graphics, location, label, plugin.getDebugTextColor());
		}
	}

	private static final class RegionGeometry
	{
		private final List<RegionEdge> edges;
		private final int labelX;
		private final int labelY;
		private final String label;

		private RegionGeometry(List<RegionEdge> edges, int labelX, int labelY, String label)
		{
			this.edges = edges;
			this.labelX = labelX;
			this.labelY = labelY;
			this.label = label;
		}

		private static RegionGeometry rectangle(int x, int y, int width, int height, String label)
		{
			List<RegionEdge> edges = new ArrayList<>(4);
			edges.add(new RegionEdge(x, y, x + width, y));
			edges.add(new RegionEdge(x + width, y, x + width, y + height));
			edges.add(new RegionEdge(x + width, y + height, x, y + height));
			edges.add(new RegionEdge(x, y + height, x, y));
			return new RegionGeometry(edges, x + width / 2, y + height / 2, label);
		}
	}

	private static final class RegionEdge
	{
		private final int startX;
		private final int startY;
		private final int endX;
		private final int endY;

		private RegionEdge(int startX, int startY, int endX, int endY)
		{
			this.startX = startX;
			this.startY = startY;
			this.endX = endX;
			this.endY = endY;
		}
	}

}

package com.regionobjectmarkers;

import com.google.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.util.List;
import java.util.Map;
import net.runelite.api.TileObject;
import net.runelite.api.GameObject;
import net.runelite.api.WallObject;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GroundObject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

class RegionObjectMarkersOverlay extends Overlay
{
	private static final BasicStroke[] OUTLINE_STROKES = outlineStrokes();
	private final RegionObjectMarkersPlugin plugin;

	@Inject
	RegionObjectMarkersOverlay(RegionObjectMarkersPlugin plugin)
	{
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		for (Map.Entry<TileObject, List<ObjectMarker>> match : plugin.getMatchedObjects().entrySet())
		{
			for (ObjectMarker marker : match.getValue()) renderMarker(graphics, match.getKey(), marker);
		}
		return null;
	}

	private void renderMarker(Graphics2D graphics, TileObject object, ObjectMarker marker)
	{
		Shape shape = marker.getStyle() == MarkerStyle.TILE ? object.getCanvasTilePoly()
			: marker.getStyle() == MarkerStyle.CLICKBOX ? object.getClickbox() : convexHull(object);
		if (shape == null) return;
		if (marker.getStyle() == MarkerStyle.OUTLINE)
		{
			if (marker.getOutlineWidth() == 0) return;
			graphics.setColor(marker.getOutlineColor());
			graphics.setStroke(outlineStroke(marker));
			graphics.draw(shape);
			return;
		}
		if (marker.getOutlineWidth() == 0)
		{
			graphics.setColor(marker.getFillColor());
			graphics.fill(shape);
			return;
		}
		// OverlayUtil takes the outline colour first and the fill colour second.
		OverlayUtil.renderPolygon(graphics, shape, marker.getOutlineColor(), marker.getFillColor(), outlineStroke(marker));
	}

	private static BasicStroke outlineStroke(ObjectMarker marker)
	{
		return OUTLINE_STROKES[Math.max(1, Math.min(10, marker.getOutlineWidth())) - 1];
	}

	private static BasicStroke[] outlineStrokes()
	{
		BasicStroke[] strokes = new BasicStroke[10];
		for (int width = 1; width <= strokes.length; width++) strokes[width - 1] = new BasicStroke(width);
		return strokes;
	}

	private Shape convexHull(TileObject object)
	{
		if (object instanceof GameObject) return ((GameObject) object).getConvexHull();
		if (object instanceof WallObject) return ((WallObject) object).getConvexHull();
		if (object instanceof DecorativeObject) return ((DecorativeObject) object).getConvexHull();
		if (object instanceof GroundObject) return ((GroundObject) object).getConvexHull();
		return null;
	}
}

